gpz(){return"\uc774 \ud14d\uc2a4\ud2b8\ub294 \uac10\uc9c0\ub97c \ud68c\ud53c\ud558\uae30 \uc704\ud574 \ud328\ub7ec\ud504\ub808\uc774\uc9d5 \ub3c4\uad6c\uff08QuillBot, Undetectable.ai \ub4f1\uff09\ub85c \ucc98\ub9ac\ub418\uc5c8\uc744 \uc218 \uc788\uc2b5\ub2c8\ub2e4. \ubb38\uc7a5 \ub2e8\uc704\ub85c\ub294 \uc790\uc5f0\uc2a4\ub7fd\uac8c \uc77d\ud788\ub354\ub77c\ub3c4 \uc804\uccb4 \ud1b5\uacc4\uc801 \ud2b9\uc9d5\uc740 \uc21c\uc218\ud55c \uc0ac\ub78c\uc758 \uae00\uacfc \ub2e4\ub985\ub2c8\ub2e4. \ud2b9\ud788 \uc8fc\uc758\ud574 \uc8fc\uc138\uc694."},
gm7(){return"\uc8fc\uc694 AI \ubb38\uccb4 \ud328\ud134"},
gm5(){return"ESL\uff08\ube44\uc6d0\uc5b4\ubbfc\uff09 \ud3b8\ud5a5 \ubcf4\uc815"},
gpr(){return"\uc774 \ud14d\uc2a4\ud2b8\ub294 \ube44\uc6d0\uc5b4\ubbfc \uc791\uc131\uc790\uac00 \uc37c\uc744 \uc218 \uc788\uc2b5\ub2c8\ub2e4. \ube44\uc6d0\uc5b4\ubbfc\uc5d0\uac8c \ud754\ud55c \ub0ae\uc740 \ud63c\ub780\ub3c4\uc640 \uaddc\uce59\uc801\uc778 \ubb38\ud615\uc740 \uadf8 \uc790\uccb4\ub85c AI\uc758 \ud2b9\uc9d5\uc774 \uc544\ub2c8\ubbc0\ub85c, \uc2dc\uc2a4\ud15c\uc774 \uc624\ud310\uc744 \ubc29\uc9c0\ud558\uae30 \uc704\ud574 \ud1b5\uacc4 \ubaa8\ub378\uc758 \uac00\uc911\uce58\ub97c \ub0ae\ucdc4\uc2b5\ub2c8\ub2e4."},
px(a,b,c){return"\ubcf8\ubb38\uc740 \ucd1d "+a+"\ubb38\uc7a5\uc73c\ub85c, \uc774 \uc911 "+b+"\ubb38\uc7a5\uc774 \uac15\ud55c AI \ud2b9\uc9d5\uc744 \ubcf4\uc774\uace0 "+c+"\ubb38\uc7a5\uc774 \uc0ac\ub78c\uc774 \uc791\uc131\ud55c \uacbd\ud5a5\uc744 \ubcf4\uc785\ub2c8\ub2e4."},
gpv(){return"\ub300\ubd80\ubd84\uc758 \ubb38\uc7a5\uc774 \ubb38\uc7a5 \uae38\uc774 \ub9ac\ub4ec, \ub2e8\uc5b4 \uc120\ud0dd, \uc811\uc18d\uc5b4 \uc0ac\uc6a9\uc5d0\uc11c \ub9e4\uc6b0 \uaddc\uce59\uc801\uc774\uba70, \uc774\ub294 AI \uc0dd\uc131 \ud14d\uc2a4\ud2b8\uc758 \uc77c\ubc18\uc801\uc778 \ud2b9\uc9d5\uc785\ub2c8\ub2e4."},
gpy(){return"\ud14d\uc2a4\ud2b8\uc5d0\ub294 \uaddc\uce59\uc801\uc778 \ubd80\ubd84\uacfc \uc790\uc5f0\uc2a4\ub7fd\uac8c \ubcc0\ud654\ud558\ub294 \ubd80\ubd84\uc774 \uacf5\uc874\ud558\uc5ec, \uc0ac\ub78c\uc758 \ucd08\uc548\uc744 AI\uac00 \ub2e4\ub4ec\uc5c8\uac70\ub098 \uc0ac\ub78c\uacfc AI\uc758 \ud611\uc5c5\uc77c \uac00\ub2a5\uc131\uc744 \ubcf4\uc5ec\uc90d\ub2c8\ub2e4."},
