pQ(a){return"\ubb38\uc7a5 \uae38\uc774\uc5d0 \ub69c\ub837\ud55c \ubcc0\ud654\uac00 \uc788\uc2b5\ub2c8\ub2e4\uff08burstiness "+a+"\uff09. \ucd5c\uc2e0 AI \ucd9c\ub825\uacfc \ubb38\uc11c \ub808\uc774\uc544\uc6c3\ub3c4 \ube44\uc2b7\ud55c \uac12\uc744 \ub9cc\ub4e4\uae30 \ub54c\ubb38\uc5d0 \uc0ac\ub78c\uc774 \uc37c\ub2e4\ub294 \uc99d\uac70\ub85c \ubcf4\uc9c0 \uc54a\uc2b5\ub2c8\ub2e4"},
pS(a){return"\ubb38\uc7a5 \uae38\uc774 \ubcc0\ub3d9(\ubc84\uc2a4\ud2f0\ub2c8\uc2a4 "+a+")\uc774 \uc911\ub9bd \uad6c\uac04 0.30~0.55 \uc548\uc5d0 \uba38\ubb3c\ub800\uc2b5\ub2c8\ub2e4"},
qi(a){return"\uc5b4\ud718 \ub2e4\uc591\uc131\uc774 \ub0ae\uace0\uff08TTR "+a+"\uff09\ub2e8\uc5b4 \ubc18\ubcf5\ub3c4\uac00 \ub192\uc2b5\ub2c8\ub2e4"},
