qb(a){return"\uc804\uccb4 \ud1b5\uacc4 \uc694\uc57d: AI \uc0dd\uc131 \ud2b9\uc131 \ucabd\uc73c\ub85c \uae30\uc6b8\uc5b4\uc9d0\uff08AI \ud655\ub960 "+a+"%\uff09"},
qc(a){return"\uc804\uccb4 \ud1b5\uacc4 \uc694\uc57d: \uc790\uc5f0\uc2a4\ub7ec\uc6b4 \uc778\uac04 \uae00\uc4f0\uae30 \ucabd\uc73c\ub85c \uae30\uc6b8\uc5b4\uc9d0\uff08AI \ud655\ub960 "+a+"%\uff09"},
