qa(a){return"\uc5ec\ub7ec \uc778\uc811 \ubb38\uc7a5\uc774 \uac19\uc740 \ub2e8\uc5b4\ub85c \uc2dc\uc791\ud558\uba70\uff08"+a+"\uacf3\uff09\ubb38\ud615\uc774 \ubc18\ubcf5\ub429\ub2c8\ub2e4"},
