q0(a){return"PAN 2025 \uc5b4\ud718 \uc9c0\ubb38\uc774 AI \ucabd\uc73c\ub85c \uae30\uc6b8\uc5c8\uc2b5\ub2c8\ub2e4("+a+"/100). \uc774 \ub3c5\ub9bd\uc801\uc778 \uc601\uc5b4 \uae30\uc900\uc120\uc740 \uc0ac\ub78c \ub9d0\ubb49\uce58\uc640 \ub2e4\ub978 \ub2e8\uc5b4\xb7\uad6c \ubd84\ud3ec\ub97c \ud0d0\uc9c0\ud569\ub2c8\ub2e4"},
q1(a){return"PAN 2025 \uc5b4\ud718 \uc9c0\ubb38\uc774 \uc0ac\ub78c \ucabd\uc73c\ub85c \uae30\uc6b8\uc5c8\uc2b5\ub2c8\ub2e4("+a+"/100). \uc774\ub294 \ubaa8\ub378\uc774 \uc81c\uc2dc\ud55c \uadfc\uac70\uc77c \ubfd0 \uc791\uc131\uc790\ub97c \uc99d\uba85\ud558\uc9c0\ub294 \uc54a\uc2b5\ub2c8\ub2e4"},
q2(a){return"PAN 2025 \uc5b4\ud718 \uc9c0\ubb38\uc740 \uc911\ub9bd\uc774\uba70("+a+"/100) \ubc29\ud5a5\uc744 \uc81c\uc2dc\ud558\uc9c0 \uc54a\uc2b5\ub2c8\ub2e4"},
pU(a){return"DetectRL-ZH\uc758 \uc911\uad6d\uc5b4 \ubb38\uc790 \uc9c0\ubb38\uc774 \ubcf4\uc218\uc801\uc778 AI \uadfc\uac70 \uae30\uc900\uc120\uc744 \ub118\uc5c8\uc2b5\ub2c8\ub2e4("+a+"/100). \uc774 \uc9c0\ubb38\uc740 DeepSeek-V3, \ud63c\ud569 \ud14d\uc2a4\ud2b8, \uc5ed\ubc88\uc5ed, \ubb38\uc790 \uad50\ub780, \ub2e4\uc591\ud55c \uae38\uc774\uc5d0 \ub300\ud574 \ub3c5\ub9bd\uc801\uc73c\ub85c \uac80\uc99d\ub418\uc5c8\uc2b5\ub2c8\ub2e4"},
pV(a){return"DetectRL-ZH\uc758 \uc911\uad6d\uc5b4 \ubb38\uc790 \uc9c0\ubb38\uc774 \ubcf4\uc218\uc801\uc778 AI \uadfc\uac70 \uae30\uc900\uc120\uc744 \ub118\uc9c0 \ubabb\ud588\uc2b5\ub2c8\ub2e4("+a+"/100). \uc774\ub294 \ud310\ub2e8 \ubcf4\ub958\uc774\uba70, \uc0ac\ub78c\uc774 \uc791\uc131\ud588\ub2e4\ub294 \uadfc\uac70\uac00 \uc544\ub2d9\ub2c8\ub2e4"},
pT(a){return"\uacbd\uacc4\ub97c \ub118\ub294 \uc555\ucd95 \uc77c\uad00\uc131("+a+")\uc774 PAN 2025\uc758 \uc0ac\ub78c 95 \ubc31\ubd84\uc704 \uc120\ubcc4 \uae30\uc900\uc744 \ub118\uc5c8\uc2b5\ub2c8\ub2e4[AI \ucabd \uc57d\ud55c \uc2e0\ud638]"},
pP(a){return"\uc694\uccad\uc790\uc5d0\uac8c \ub9d0\uc744 \uac78\uac70\ub098 \uc694\uccad\ud55c \uae00\uc744 \uace0\uccd0\uc8fc\uaca0\ub2e4\uace0 \uc81c\uc548\ud558\ub294 \ub4f1, \ub300\ud654\ud615 \uc5b4\uc2dc\uc2a4\ud134\ud2b8 \uc751\ub2f5\uc758 \ud754\uc801\uc744 "+a+"\uac74 \ubc1c\uacac\ud588\uc2b5\ub2c8\ub2e4"},
gpN(){return"\ud328\ub7ec\ud504\ub808\uc774\uc988 \uac10\uc9c0 \ubaa8\ub378\uc774 \uc124\uce58\ub418\uc9c0 \uc54a\uc544 \uc774\ubc88 \ud22c\ud45c\uc5d0 \ucc38\uc5ec\ud558\uc9c0 \uc54a\uc558\uc2b5\ub2c8\ub2e4"},
gqf(){return"\ubaa8\ub378\uc774 \uc124\uce58\ub418\uc9c0 \uc54a\uc558\uac70\ub098 \uc0ac\uc6a9 \uc911\uc778 \ubaa8\ub378\uc774 \uc9c0\uc6d0\ub418\uc9c0 \uc54a\uc544 \uc774\ubc88 \ud22c\ud45c\uc5d0 \ucc38\uc5ec\ud558\uc9c0 \uc54a\uc558\uc2b5\ub2c8\ub2e4"},
gv1(){return"\ud65c\uc131\ud654\ub41c \ubaa8\ub378\uc744 \ucc3e\uc744 \uc218 \uc5c6\uc2b5\ub2c8\ub2e4. \ubaa8\ub378 \uad00\ub9ac\uc5d0\uc11c \ucd94\ucc9c \ubaa8\ub378\uc744 \ub2e4\uc6b4\ub85c\ub4dc\ud558\uc138\uc694."},
gv0(){return"\ub85c\ub4dc\uc5d0 \uc2e4\ud328\ud55c \uc0ac\uc6a9\uc790 \uc9c0\uc815 \ubaa8\ub378\uc744 \uc81c\uac70\ud588\uc2b5\ub2c8\ub2e4. \uc0ac\uc6a9\uc790 \uc9c0\uc815 \ubaa8\ub378\uc740 \uc790\ub3d9\uc73c\ub85c \ub2e4\uc2dc \ub2e4\uc6b4\ub85c\ub4dc\ud560 \uc218 \uc5c6\uc73c\ubbc0\ub85c \ubaa8\ub378\uacfc \ud1a0\ud06c\ub098\uc774\uc800\ub97c \ub2e4\uc2dc \uac00\uc838\uc624\uc138\uc694."},
gv2(){return"\ub85c\ub4dc\uc5d0 \uc2e4\ud328\ud55c \ubaa8\ub378 \ud30c\uc77c\uc744 \uc81c\uac70\ud588\uc9c0\ub9cc \ub2e4\uc2dc \ub2e4\uc6b4\ub85c\ub4dc\ud560 \uc218 \uc788\ub294 \uce74\ud0c8\ub85c\uadf8 \uc18c\uc2a4\ub97c \ucc3e\uc744 \uc218 \uc5c6\uc2b5\ub2c8\ub2e4. \ubaa8\ub378 \uad00\ub9ac\uc5d0\uc11c \ucd94\ucc9c \ubaa8\ub378\uc744 \ub2e4\uc2dc \ub2e4\uc6b4\ub85c\ub4dc\ud558\uc138\uc694."},
v4(a){return"\ubaa8\ub378 \ud30c\uc77c\uc774 \uc190\uc0c1\ub418\uc5c8\uac70\ub098 \ud638\ud658\ub418\uc9c0 \uc54a\uc744 \uc218 \uc788\uc74c\uc744 \uac10\uc9c0\ud558\uc5ec "+a+"\uc744(\ub97c) \uc790\ub3d9\uc73c\ub85c \ub2e4\uc2dc \ub2e4\uc6b4\ub85c\ub4dc\ud588\uc2b5\ub2c8\ub2e4. \ubd84\uc11d\uc744 \ub2e4\uc2dc \uc2e4\ud589\ud558\uc138\uc694."},
v3(a){return"\ub85c\ub4dc\uc5d0 \uc2e4\ud328\ud55c \ubaa8\ub378 \ud30c\uc77c\uc744 \uc81c\uac70\ud588\uc9c0\ub9cc \uc790\ub3d9 \uc7ac\ub2e4\uc6b4\ub85c\ub4dc\uac00 \uc644\ub8cc\ub418\uc9c0 \uc54a\uc558\uc2b5\ub2c8\ub2e4. \ub124\ud2b8\uc6cc\ud06c \uc5f0\uacb0\uc744 \ud655\uc778\ud55c \ud6c4 \ubaa8\ub378 \uad00\ub9ac\uc5d0\uc11c "+a+"\uc744(\ub97c) \ub2e4\uc2dc \ub2e4\uc6b4\ub85c\ub4dc\ud558\uc138\uc694."},
gqr(){return"\ud65c\uc131\ud654\ub41c Transformer \ubaa8\ub378\uc744 \ucc3e\uc744 \uc218 \uc5c6\uc2b5\ub2c8\ub2e4. \ubaa8\ub378 \uad00\ub9ac\uc5d0\uc11c \ub2e4\uc6b4\ub85c\ub4dc\ud558\uac70\ub098 \ud65c\uc131\uc73c\ub85c \uc124\uc815\ud558\uc138\uc694"},
