gtH(){return"\uacb0\uacfc \ud655\uc778 \ubc0f \ub0b4\ubcf4\ub0b4\uae30"},
gtC(){return'\ub9ac\ud3ec\ud2b8 \ud398\uc774\uc9c0\uc5d0\ub294 \uc885\ud569 AI \ud655\ub960 \uac8c\uc774\uc9c0, \ubb38\uc7a5 \ub2e8\uc704 \ud788\ud2b8\ub9f5, 4\uac1c \uc5d4\uc9c4\uc758 \uc810\uc218 \ubc0f \uadfc\uac70 \uc0c1\uc138, \ud558\uc774\ud37c\ub9c1\ud06c \uc2e4\uc7ac\uc131, \uc778\uc6a9 \ubb38\ud5cc \uc2e4\uc7ac\uc131\uc774 \ud3ec\ud568\ub429\ub2c8\ub2e4. \uc804\uccb4 PDF \ub9ac\ud3ec\ud2b8, \ubb38\uc7a5\ubcc4 CSV \ub370\uc774\ud130, JSON\uff08\uc2dc\uc2a4\ud15c \uc5f0\ub3d9\uc6a9\uff09, PNG \uc694\uc57d \uce74\ub4dc\uff08\uacf5\uc720\uc6a9\uff09\ub97c \ub0b4\ubcf4\ub0bc \uc218 \uc788\uc2b5\ub2c8\ub2e4. \uac01 \ubd84\uc11d \uacb0\uacfc\ub294 \uc790\ub3d9\uc73c\ub85c "\uae30\ub85d"\uc5d0 \uc800\uc7a5\ub418\uc5b4 \uc5b8\uc81c\ub4e0\uc9c0 \ub2e4\uc2dc \ud655\uc778\ud560 \uc218 \uc788\uc2b5\ub2c8\ub2e4.'},
