zg(a,b,c,d){return""+a+"/"+d+"\uac1c \ubaa8\ub4c8 \uc644\ub8cc \xb7 "+c+"\ucd08 \uacbd\uacfc \xb7 \uc2e4\ud589 \uc911: "+b},
zi(a){return"\ubd84\uc11d\uc774 \uacc4\uc18d \uc9c4\ud589 \uc911\uc774\uba70 \ud654\uba74\uc740 \uc751\ub2f5\ud558\uace0 \uc788\uc2b5\ub2c8\ub2e4. \uc9c0\ub09c "+a+"\ucd08 \ub3d9\uc548 \uc644\ub8cc\ub41c \ubaa8\ub4c8\uc774 \uc5c6\uc2b5\ub2c8\ub2e4. \ud070 \ubb38\uc11c\ub098 \ub85c\uceec \ubaa8\ub378\uc740 \uc2dc\uac04\uc774 \ub354 \uac78\ub9b4 \uc218 \uc788\uc2b5\ub2c8\ub2e4."},
gzh(){return"\ubd84\uc11d\uc774 \uc608\uae30\uce58 \uc54a\uac8c \uc911\uc9c0\ub418\uc5c8\uc2b5\ub2c8\ub2e4. \ub2e4\uc2dc \uc2dc\ub3c4\ud558\uac70\ub098 \ubaa8\ub378 \uc124\uc815\uc744 \ud655\uc778\ud558\uc138\uc694."},
