mR(a,b){return"\u0418\u043d\u0434\u0435\u043a\u0441 "+a+" \u2014 \u043b\u0438\u0448\u044c \u0441\u043b\u0430\u0431\u043e\u0435 \u043d\u0430\u043f\u0440\u0430\u0432\u043b\u0435\u043d\u0438\u0435 \u0432 \u0441\u0442\u043e\u0440\u043e\u043d\u0443 \u0418\u0418, \u043e\u043d \u043f\u043e-\u043f\u0440\u0435\u0436\u043d\u0435\u043c\u0443 \u043d\u0430 "+b+" \u043f\u0443\u043d\u043a\u0442\u043e\u0432 \u043d\u0438\u0436\u0435 \u043b\u0438\u043d\u0438\u0438 \u043f\u043e\u0432\u044b\u0448\u0435\u043d\u0438\u044f \u0432 60 \u043f\u0443\u043d\u043a\u0442\u043e\u0432. \u0410\u0432\u0442\u043e\u0440\u0441\u0442\u0432\u043e \u0418\u0418 \u043d\u0435 \u0443\u0441\u0442\u0430\u043d\u043e\u0432\u043b\u0435\u043d\u043e."},
mS(a,b){return"\u0418\u043d\u0434\u0435\u043a\u0441 "+a+" \u0441\u043a\u043b\u043e\u043d\u044f\u0435\u0442\u0441\u044f \u043a \u0447\u0435\u043b\u043e\u0432\u0435\u043a\u0443 \u0438 \u043f\u043e-\u043f\u0440\u0435\u0436\u043d\u0435\u043c\u0443 \u043d\u0430 "+b+" \u043f\u0443\u043d\u043a\u0442\u043e\u0432 \u043d\u0438\u0436\u0435 \u043b\u0438\u043d\u0438\u0438 \u043f\u043e\u0432\u044b\u0448\u0435\u043d\u0438\u044f \u0418\u0418 \u0432 60 \u043f\u0443\u043d\u043a\u0442\u043e\u0432, \u043d\u043e \u043e\u0433\u0440\u0430\u043d\u0438\u0447\u0435\u043d\u043d\u044b\u0435 \u0434\u043e\u043a\u0430\u0437\u0430\u0442\u0435\u043b\u044c\u0441\u0442\u0432\u0430 \u043d\u0435 \u043f\u043e\u0437\u0432\u043e\u043b\u044f\u044e\u0442 \u0438\u0441\u043a\u043b\u044e\u0447\u0438\u0442\u044c \u043f\u043e\u043c\u043e\u0449\u044c \u0418\u0418."},
uc(a,b){return"\u0421\u0435\u043c\u0435\u0439\u0441\u0442\u0432\u0430 \u043d\u0430\u043f\u0440\u0430\u0432\u043b\u0435\u043d\u043d\u044b\u0445 \u0441\u0438\u0433\u043d\u0430\u043b\u043e\u0432: "+a+"/4 \xb7 \u043e\u0445\u0432\u0430\u0442 \u043f\u0440\u0438\u043c\u0435\u043d\u0438\u043c\u043e\u0441\u0442\u0438 "+b+" %"},
gue(){return"\u041f\u043e\u0440\u043e\u0433 \u0434\u043e\u043a\u0430\u0437\u0430\u0442\u0435\u043b\u044c\u0441\u0442\u0432 \u0418\u0418: \u043f\u0440\u043e\u0439\u0434\u0435\u043d"},
